<?php
require __DIR__.'/layout.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if (!$id || $id<1){http_response_code(400);exit('ID inválido');}
$stmt=db()->prepare('SELECT id,filename,mime_type,file_size,processor,sha256,hex_preview,base64_preview,description,created_at FROM documents WHERE id=:id');$stmt->execute([':id'=>$id]);$r=$stmt->fetch();if (!$r){http_response_code(404);exit('Documento não encontrado');}
page_start('Documento #'.$id); ?>
<div class="card p-4 mb-4"><div class="d-flex justify-content-between flex-wrap gap-2"><h4><?=h($r['filename'])?></h4><div><a class="btn btn-outline-primary btn-sm" href="file.php?id=<?=$id?>&download=1">Baixar original</a> <a class="btn btn-outline-secondary btn-sm" href="documents.php">Voltar</a></div></div>
<div class="row g-2"><div class="col-md-6"><b>Processador:</b> <?=h($r['processor'])?></div><div class="col-md-6"><b>Data:</b> <?=h((new DateTimeImmutable($r['created_at']))->setTimezone(new DateTimeZone('America/Sao_Paulo'))->format('d/m/Y H:i:s'))?></div><div class="col-md-6"><b>MIME:</b> <?=h($r['mime_type'])?></div><div class="col-md-6"><b>Tamanho:</b> <?=number_format((int)$r['file_size'],0,',','.')?> bytes</div><div class="col-12 text-break"><b>SHA-256:</b> <span class="mono"><?=h($r['sha256'])?></span></div><div class="col-12"><b>Descrição:</b> <?=nl2br(h($r['description']))?></div></div></div>
<div class="card p-4 mb-4"><h5>Documento original completo</h5><?php if($r['mime_type']==='application/pdf'): ?><iframe title="Visualização do PDF" class="preview w-100" src="file.php?id=<?=$id?>"></iframe><?php else: ?><img alt="Imagem original" class="img-fluid preview" style="height:auto;max-height:75vh" src="file.php?id=<?=$id?>"><?php endif; ?></div>
<div class="card p-4"><h5>Dados binários e texto gerado</h5><p class="text-secondary">O texto gerado é a codificação Base64 do arquivo, não uma transcrição OCR.</p><div class="mb-3"><b>Primeiros 128 bytes — hexadecimal</b><pre class="mono bg-light p-3 rounded text-break"><?=h($r['hex_preview'])?></pre></div><div class="mb-3"><b>Primeiros 128 bytes — Base64</b><pre class="mono bg-light p-3 rounded text-break"><?=h($r['base64_preview'])?></pre></div><a class="btn btn-outline-primary btn-sm" href="text.php?id=<?=$id?>">Ver / baixar Base64 completo</a></div>
<?php page_end(); ?>
